const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../required_members.cjs');
test('required checks presence, not truthiness or properties declarations', () => {
  for (const value of [{code:null},{code:false},{code:0},{code:''}]) assert.equal(app.hasRequired(value,{required:['code']}),true);
  assert.equal(app.hasRequired({}, {required:['code']}),false);
  assert.equal(app.hasRequired({}, {properties:{code:{type:'string'}}}),true);
  assert.equal(app.hasRequired({}, {required:[]}),true);
  assert.equal(app.hasRequired({}, {required:['toString']}),false);
  assert.equal(app.hasRequired({a:1}, {required:['a','b']}),false);
  assert.equal(app.hasRequired({a:1,b:2}, {required:['a','b']}),true);
});
